/**
 * Map pin data for the dotted India map on the About page.
 *
 * Positions are percentages of the SVG view box, generated by
 * tools/make_maps.py from real latitude / longitude values.
 */

export type MapPin = {
	id: string;
	label: string;
	/** line under the name inside the map label */
	sub?: string;
	/** state / place shown in the legend under the panel */
	place: string;
	/** second line in the legend, when it differs from the state */
	legend?: string;
	/** % from the left */
	x: number;
	/** % from the top */
	y: number;
	/** which side of the pin the label sits on */
	side: "left" | "right";
	/** vertical nudge in px, so labels in a cluster do not collide */
	dy: number;
	head?: boolean;
	/** swap the label to the other side on small screens */
	flip?: boolean;
};

